import sys
import time

start = time.time()

def array_multiply(arr):
    res = 1
    for i in arr:
        res *= i
    return res

n = sys.stdin.readline().strip()
n_length = len(n)

if n_length == 1:
    sys.exit(n)

if n[1:] == '9' * (n_length - 1):
    sys.exit(str(array_multiply(list(map(int, n)))))

n_list = list(map(int, n))
max_val = array_multiply(n_list)

for i in range(n_length - 1):
    arr = n_list[:]
    arr[i] = int(arr[i]) - 1
    for j in range(i + 1, n_length):
        arr[j] = 9
    for j in range(n_length - 1, 0, -1):
        if arr[j] == 0:
            arr[j] = 9
            arr[j - 1] -= 1
        if arr[j] == -1:
            arr[j] = 9
            arr[j - 1] -= 1
    if arr[0] == 0:
        arr = arr[1:]
    max_val = max(max_val, array_multiply(arr))

print(max_val)

